from pathlib import Path
from playwright.sync_api import sync_playwright
import json
R=Path(__file__).resolve().parent
out={}
with sync_playwright() as pw:
 b=pw.chromium.launch(channel='msedge',headless=True,args=['--allow-file-access-from-files'])
 c=b.new_context(offline=True,viewport={'width':1440,'height':1080});p=c.new_page();p.goto((R/'cameroon-v1.html').as_uri());p.wait_for_function('pilot.ready')
 out['features']=p.evaluate('''(()=>{let relief=0,canopies=0,maps=[],wrong=[],span=null;const seen=new Set();pilot.root.traverse(o=>{if(!o.isMesh)return;if(o.name.startsWith('Fako')||o.name.startsWith('Rainforest')){let a=o.parent;while(a&&a.name!=='Lid_Hinge')a=a.parent;if(!a)wrong.push(o.name);if(o.name.startsWith('Fako')){relief++;let a=o.geometry.attributes.position;let mn=[Infinity,Infinity,Infinity],mx=[-Infinity,-Infinity,-Infinity];for(let i=0;i<a.count;i++){let v=pilot.root.position.clone().fromBufferAttribute(a,i).applyMatrix4(o.matrixWorld);[v.x,v.y,v.z].forEach((x,j)=>{mn[j]=Math.min(mn[j],x);mx[j]=Math.max(mx[j],x)});}span=span?{min:mn.map((v,j)=>Math.min(v,span.min[j])),max:mx.map((v,j)=>Math.max(v,span.max[j]))}:{min:mn,max:mx};}else canopies++;}for(let key of ['map','roughnessMap','normalMap']){let t=o.material[key];if(t&&!seen.has(t.uuid)){seen.add(t.uuid);let im=t.image,canvas=document.createElement('canvas');canvas.width=im.width;canvas.height=im.height;let ctx=canvas.getContext('2d');ctx.drawImage(im,0,0);let d=ctx.getImageData(0,0,im.width,im.height).data,mn=255,mx=0;for(let i=(key==='roughnessMap'?1:0);i<d.length;i+=4){mn=Math.min(mn,d[i]);mx=Math.max(mx,d[i]);}maps.push({key,width:im.width,height:im.height,range:mx-mn});}}});return {relief,canopies,maps,wrong,span:span.max.map((v,j)=>v-span.min[j])}})()''')
 f=out['features'];assert f['relief']==2 and f['canopies']==100 and not f['wrong'];assert f['span'][0]>=1.7 and .35<f['span'][1]<.85
 assert len(f['maps'])>=3 and all(x['range']>0 and max(x['width'],x['height'])<=1024 for x in f['maps'])
 p.locator('#open').click();p.wait_for_function('pilot.progress===1');box=p.locator('canvas').bounding_box();x=box['x']+box['width']*.5;y=box['y']+box['height']*.5;p.mouse.move(x,y);p.mouse.down();p.mouse.move(x+box['height']*.5,y,steps=30);p.mouse.up();p.wait_for_timeout(150);p.screenshot(path=str(R/'desktop-open-rear.png'),full_page=True);c.close()
 c=b.new_context(offline=True,java_script_enabled=False,viewport={'width':390,'height':844});p=c.new_page();p.goto((R/'cameroon-v1.html').as_uri());assert p.locator('#fallback').is_visible();assert p.locator('#fallback').evaluate('(e)=>e.complete&&e.naturalWidth>0');p.screenshot(path=str(R/'mobile-nojs.png'),full_page=True);out['noJS_poster']=True;c.close();b.close()
out['status']='PASS';(R/'extended-check.json').write_text(json.dumps(out,indent=2));print(json.dumps(out,indent=2))
